//! The registry of nerpa: decisions, specifications, plan and journal, written as
//! code on dacc's methodology.
//!
//! A reference between records is a path to a constant generated by the scan at
//! build time, so a record that names a document that no longer exists does not
//! compile. Records carry no state: a work item's state is the fold of the
//! append-only journal, available as [`WORK_STATES`] and [`CLOSED_SLICES`].
//!
//! Layout: `adr/` — decisions, `rfc/` — specifications, `thrust/` — thrusts,
//! `slice/` — slices, `work/` — work items, `journal/` — events, `taxonomy.rs` —
//! the subsystem and team axes. The invariant and review registries ride on
//! dacc-knowledge's types (adr-2026-068); `proposal/` keeps its local type.

pub mod proposal;
pub mod taxonomy;

// Generated by build.rs: the document modules, reference constants, lists,
// compile-time classification checks and the journal fold.
include!(concat!(env!("OUT_DIR"), "/adr.rs"));
include!(concat!(env!("OUT_DIR"), "/rfc.rs"));
include!(concat!(env!("OUT_DIR"), "/plan.rs"));
include!(concat!(env!("OUT_DIR"), "/journal.rs"));
include!(concat!(env!("OUT_DIR"), "/anchor.rs"));

/// Where a superseded decision names its successor: the variant holds the
/// reference, so a successor that does not exist cannot be named
/// (INV-PILOT-004).
#[dacc_derive::doc_anchor(id = "the-superseded-variant-carries-its-successor")]
pub fn successor_of(status: &dacc_knowledge::DocStatus) -> Option<&'static str> {
    match status {
        dacc_knowledge::DocStatus::SupersededBy(successor) => Some(successor.as_str()),
        _ => None,
    }
}

/// What the conversion carried lives in the record's context field
/// (INV-PILOT-006).
#[dacc_derive::doc_anchor(id = "the-sections-live-in-the-records-context")]
pub fn sections_of(decision: &dacc_knowledge::ArchitectureDecision) -> &str {
    decision.context
}

#[cfg(test)]
mod tests {
    use super::*;
    use dacc_journal::{Evidence, Kind, read_dir, read_file};

    /// The registries are not empty and every record has a title. The
    /// non-emptiness of authors and invariants is held by the type; this checks
    /// only what the type cannot express.
    #[test]
    fn registries_are_not_empty() {
        assert!(!ALL.is_empty(), "decision registry is empty");
        assert!(!ALL_SPECS.is_empty(), "specification registry is empty");
        assert!(!ALL_THRUSTS.is_empty(), "thrust registry is empty");
        assert!(!ALL_SLICES.is_empty(), "slice registry is empty");
        assert!(!ALL_WORK.is_empty(), "work registry is empty");
        assert!(!ALL_REVIEWS.is_empty(), "review registry is empty");
        assert!(!ALL_INVARIANTS.is_empty(), "invariant registry is empty");
        assert!(
            !proposal::ALL_PROPOSALS.is_empty(),
            "proposal registry is empty"
        );
        for (_, d) in ALL {
            assert!(!d.title.trim().is_empty(), "decision without a title");
        }
        for (_, s) in ALL_SPECS {
            assert!(!s.title.trim().is_empty(), "specification without a title");
        }
    }

    /// The journal fold yields a state for every planned work item.
    #[test]
    fn every_work_has_a_state_from_the_journal() {
        assert_eq!(WORK_STATES.len(), ALL_WORK.len());
    }

    /// A reference to a record that no longer exists does not compile
    /// (INV-PILOT-001), and where a reference names a record of another kind
    /// than the field asks for, this walk sees it.
    #[dacc_derive::doc_anchor(id = "every-reference-names-a-record-of-its-kind")]
    #[test]
    fn every_reference_names_a_record_of_its_kind() {
        let same = |left: &str, right: &str| left.replace('_', "-") == right.replace('_', "-");
        for (slug, spec) in ALL_SPECS {
            for decision in spec.decided_by {
                assert!(
                    ALL.iter().any(|(other, _)| same(other, decision.as_str())),
                    "{slug} is decided by a decision that is not in the registry"
                );
            }
        }
        for work in ALL_WORK {
            assert!(
                ALL_SLICES
                    .iter()
                    .any(|slice| same(slice.id, work.slice.as_str())),
                "{} belongs to a slice that is not in the registry",
                work.id
            );
        }
        for slice in ALL_SLICES {
            assert!(
                ALL_THRUSTS
                    .iter()
                    .any(|thrust| same(thrust.id, slice.thrust.as_str())),
                "{} belongs to a thrust that is not in the registry",
                slice.id
            );
            assert!(
                ALL_SPECS
                    .iter()
                    .any(|(other, _)| same(other, slice.specification.as_str())),
                "{} realizes a specification that is not in the registry",
                slice.id
            );
        }
    }

    /// A work item cannot be landed without a gate proof recorded on the same
    /// tree (INV-PILOT-002): every gated landing in the journal carries its
    /// gate on the same tree. A landing restored from history carries no gate
    /// by design and says so — `evidence = "history"`.
    #[dacc_derive::doc_anchor(id = "every-gated-landing-carries-its-gate-on-the-same-tree")]
    #[test]
    fn every_gated_landing_carries_its_gate_on_the_same_tree() {
        let manifest = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
        let (mut events, _) = read_file(&manifest.join("journal.toml")).unwrap_or_default();
        let (from_dirs, _) = read_dir(&manifest.join("journal")).unwrap_or_default();
        events.extend(from_dirs);
        let mut gated = 0;
        for event in &events {
            if let Kind::Landed {
                tree,
                evidence: Evidence::Gate,
                ..
            } = &event.kind
            {
                assert!(
                    events.iter().any(|other| {
                        other.subject == event.subject
                            && matches!(&other.kind, Kind::Gate { tree: same, .. } if same == tree)
                    }),
                    "a landing without its gate on the same tree: {}",
                    event.subject.id()
                );
                gated += 1;
            }
        }
        assert!(gated > 0, "no gated landing to walk");
    }

    /// A superseded decision names a successor, and that successor exists
    /// (INV-PILOT-004).
    #[dacc_derive::doc_anchor(id = "a-superseded-decision-names-a-successor-that-exists")]
    #[test]
    fn a_superseded_decision_names_a_successor_that_exists() {
        let mut superseded = 0;
        for (slug, decision) in ALL {
            if let Some(successor) = successor_of(&decision.status) {
                assert!(
                    ALL.iter().any(|(other, _)| *other == successor),
                    "{slug} names {successor}, which is not a decision of this registry"
                );
                superseded += 1;
            }
        }
        assert!(superseded > 0, "no superseded decision to walk");
    }

    /// No work item lands with a radius above its slice's ceiling
    /// (INV-PILOT-005): the build asserts it, and the same predicate runs here.
    #[dacc_derive::doc_anchor(id = "the-radius-ceiling-holds-over-the-plan")]
    #[test]
    fn the_radius_ceiling_holds_over_the_plan() {
        for work in ALL_WORK {
            assert!(
                dacc_work::radius_within_slice(work, ALL_SLICES),
                "the radius of {} is above its slice's ceiling",
                work.id
            );
        }
    }

    /// Converting a record loses nothing (INV-PILOT-006): the sections the
    /// conversion carried are in the context field, and this looks at the
    /// residue beside v0001's byte-for-byte measurement.
    #[dacc_derive::doc_anchor(id = "a-converted-record-keeps-its-sections-in-context")]
    #[test]
    fn a_converted_record_keeps_its_sections_in_context() {
        for (slug, decision) in ALL {
            assert!(
                !sections_of(decision).trim().is_empty(),
                "{slug} lost the sections the conversion carried"
            );
        }
    }
}
